/* 第一章《三角形》材料整理：全等与判定。 */
TID("t04","1.2","全等图形的对应关系","能够完全重合的两个图形叫全等形；全等三角形的对应边相等、对应角相等。书写全等式时，对应顶点要写在对应位置。","先根据全等式确定顶点对应关系，再由对应角、对应边相等求角度或长度；必要时结合三角形内角和。","不能只凭图形摆放方向判断对应关系；周长相等或面积相等不能反推两个三角形全等。",
 Q("选择题","两个全等三角形在点 C 附近重叠。已知对应角关系可得 ∠ACA′=∠BCB′，且 ∠A′CB=30°、∠ACB′=110°，则 ∠ACA′ 的度数为（　）。","D",["由全等关系得 ∠ACA′=∠BCB′。","∠ACA′+∠A′CB+∠BCB′=∠ACB′。","设 ∠ACA′=x，则 2x+30°=110°，得 x=40°。"],["20°","30°","35°","40°"]),
 Q("填空题","已知 △ABC≌△CDA，∠BAC=85°，∠ABC=30°，则 ∠DCA=____，∠CDA=____，∠BCA=∠DAC=____。","85°；30°；65°",["在 △ABC 中，∠BCA=180°−85°−30°=65°。","由全等三角形对应角相等，∠DCA=∠BAC=85°，∠CDA=∠ABC=30°，∠DAC=∠BCA=65°。"],[]),
 Q("填空题","△ABC≌△A′B′C′，其中 ∠A=36°，∠C′=24°，则 ∠B=____。","120°",["由全等关系，∠C=∠C′=24°。","∠B=180°−36°−24°=120°。"],[]),
 Q("填空题","已知 △ABC≌△ADE，AB=11 cm，CA=5 cm，则 AD=____cm，EA=____cm。","11；5",["由全等式可知 AB 对应 AD，CA 对应 EA。","所以 AD=AB=11，EA=CA=5。"],[]));

TID("c1-05","1.2","全等性质求线段与折叠","全等三角形不仅对应边、对应角相等，对应边上的中线、高、对应角平分线也相等；翻折前后的图形是全等形。","线段题先用对应边相等，再做线段和差；折叠题把折痕两侧对应点、对应边和对应角写清楚。","折叠后的点名改变但对应关系不变；求线段时注意共线点的先后位置。",
 Q("填空题","△ABC≌△DEF，图中 BC=5，则 EF=____。","5",["由全等三角形对应边相等，BC 对应 EF。","所以 EF=5。"],[]),
 Q("解答题","已知 △ACE≌△DBF，A、B、C、D 依次在同一直线上，AD=8，BC=3。（1）求 AC；（2）CE 与 BF 是否平行？说明理由。","（1）AC=5.5；（2）CE∥BF",["由全等关系 AC=DB。令 AB=CD=x，则 AC=x+3，DB=3+x，所以二者相等。","AD=AB+BC+CD=2x+3=8，得 x=2.5，因此 AC=2.5+3=5.5。","由全等三角形对应角相等，∠ACE=∠DBF，因此 CE∥BF。"],[]),
 Q("填空题","在长方形 ABCD 中，将 △ADE 沿 AE 折叠，使 D 落在 BC 上的 F 点。若 AD=9 cm，DE=2.4 cm，∠BAF=60°，则 AF=____cm，EF=____cm，∠DAE=____。","9；2.4；15°",["折叠得到 △ADE≌△AFE，所以 AD=AF、DE=EF、∠DAE=∠FAE。","∠BAD=90°，∠FAD=90°−60°=30°。","AE 平分 ∠FAD，因此 ∠DAE=15°。"],[]),
 Q("填空题","将长方形 ABCD 沿 AE 折叠，D 的对应点为 D′。若 ∠CED′=56°，则 ∠AED=____。","62°",["折叠使 △ADE≌△AD′E，所以 ∠AED=∠AED′。","D、E、C 共线，∠AED+∠AED′+∠CED′=180°。","2∠AED=180°−56°=124°，得 ∠AED=62°。"],[]));

TID("t05","1.3","SSS、SAS 与全等条件补充","SSS：三边分别相等的两个三角形全等；SAS：两边及其夹角分别相等的两个三角形全等。公共边、对顶角、线段和差常作为隐含条件。","先列出已知相等条件，再寻找公共边、对顶角或由线段和差得到的相等；使用 SAS 时必须确认相等角是两边的夹角。","SSA（两边及其中一边的对角对应相等）不能作为一般三角形全等判定条件。",
 Q("证明题","A、D、C、B 在同一直线上，AD=BC，AE=BF，CE=DF。证明 AE∥FB。","AE∥FB",["由 AD=BC，得 AC=BD。","在 △ACE 和 △BDF 中，AC=BD、AE=BF、CE=DF，所以 △ACE≌△BDF（SSS）。","对应角 ∠A=∠B，所以 AE∥FB。"],[]),
 Q("证明题","AB=AD，BC=DC，连接 AC。证明 AC 平分 ∠BAD。","∠BAC=∠DAC",["在 △ABC 与 △ADC 中，AB=AD，BC=DC，AC 为公共边。","所以 △ABC≌△ADC（SSS）。","对应角相等，∠BAC=∠DAC，因此 AC 平分 ∠BAD。"],[]),
 Q("证明题","线段 AC、BD 相交于 E，AE=DE，BE=CE。证明 △ABE≌△DCE。","△ABE≌△DCE（SAS）",["∠AEB=∠DEC（对顶角）。","AE=DE，BE=CE。","两边及其夹角分别相等，所以 △ABE≌△DCE（SAS）。"],[]),
 Q("选择题","AB 平分 ∠DAC，要用 SAS 判定 △ABC≌△ABD，还需要补充条件（　）。","C",["AB 是公共边，且 ∠CAB=∠DAB。","SAS 还需夹角另一边相等，即 AC=AD。"],["DB=CB","∠ABC=∠ABD","AD=AC","∠D=∠C"]));

TID("t06","1.3","ASA、AAS 与直角三角形全等","ASA：两角及其夹边分别相等的两个三角形全等；AAS：两角分别相等且其中一组等角的对边也相等的两个三角形全等。直角、对顶角、平行线和角平分线常用于找等角。","已知两角时，若找到夹边用 ASA，找到其中一角的对边用 AAS；直角三角形中可利用两个直角相等和余角关系补足等角。","只有两角相等只能说明形状相同，不能判定全等；书写全等式时对应顶点顺序要一致。",
 Q("证明题","AB=AC，AB⊥AC，AD⊥AE，且 ∠ABD=∠ACE。证明 BD=CE。","BD=CE",["由 AB⊥AC、AD⊥AE，得 ∠BAD=∠CAE（同角的余角相等）。","在 △ABD 和 △ACE 中，∠BAD=∠CAE、AB=AC、∠ABD=∠ACE。","所以 △ABD≌△ACE（ASA），从而 BD=CE。"],[]),
 Q("证明题","AB∥CD，AF∥DE，BE=CF。证明 AB=DC。","AB=DC",["由 AB∥CD，得 ∠B=∠C；由 AF∥DE，得 ∠AFB=∠DEC。","BE=CF，所以 BF=CE。","△ABF≌△DCE（ASA），故 AB=DC。"],[]),
 Q("证明题","D 在 △ABC 的边 AB 上，∠A=∠ACF，DF 与 AC 交于 E，DE=EF。证明 AE=CE。","AE=CE",["∠AED=∠CEF（对顶角）。","在 △ADE 和 △CFE 中，∠A=∠ACF、∠AED=∠CEF、DE=EF。","所以 △ADE≌△CFE（AAS），故 AE=CE。"],[]),
 Q("解答题","在 Rt△ABC 中，BC=AC，∠ACB=90°。若 AD⊥EC 于 D，BE⊥EC 于 E，判断 △BEC 与 △CDA 是否全等，并说明理由。","全等，△BEC≌△CDA（AAS）",["AD⊥EC、BE⊥EC，所以 ∠E=∠ADC=90°。","∠BCE+∠ACE=90°，∠ACE+∠CAD=90°，所以 ∠BCE=∠CAD。","BC=CA，因此 △BEC≌△CDA（AAS）。"],[]));

TID("c1-06","1.3","SAS 条件补充与综合","SAS 中相等角必须是两组对应边的夹角；平行线可给出等角，共线线段可通过和差得到相等边，正方形可提供等边和直角。","先把已知条件转换为“边—夹角—边”三项；若边不是直接相等，可利用公共线段或线段和差。","不要把 SSA 当成 SAS；看到平行或正方形时要把隐含的等角、等边明确写出。",
 Q("选择题","A、B、C、D 依次在同一直线上，AE∥DF，AE=DF。要使 △EAC≌△FDB，还需添加（　）。","A",["由 AE∥DF，得 ∠A=∠D。","已知 AE=DF；若 AB=CD，则加上公共段 BC 可得 AC=DB。","于是满足 SAS。"],["AB=CD","EC=BF","∠A=∠D","AB=BC"]),
 Q("填空题","已知 AB=AC，要用 SAS 证明 △ABD≌△ACE，且两三角形在 A 处有公共夹角，还需添加条件____。","AD=AE",["已知 AB=AC，且 A 处夹角相等。","要用 SAS，还需夹角另一边对应相等，所以 AD=AE。"],[]),
 Q("证明题","A、B、C、D 在同一直线上，AC=BD，∠1=∠2，EC=FB。证明 △DBF≌△ACE。","△DBF≌△ACE（SAS）",["由 ∠1=∠2 得 ∠FBD=∠ECA。","FB=EC，BD=CA。","两边及其夹角相等，所以 △DBF≌△ACE（SAS）。"],[]),
 Q("解答题","在正方形 ABCD 中，E、F 分别在 CD、AD 上，AF=CE。（1）证明 △ABF≌△CBE；（2）若 AB=4，AF=1，求四边形 BEDF 的面积。","（1）△ABF≌△CBE（SAS）；（2）12",["正方形中 AB=CB，∠A=∠C=90°，且 AF=CE，所以 △ABF≌△CBE（SAS）。","正方形面积为 4²=16。","S△ABF=S△CBE=4×1÷2=2。","四边形 BEDF 面积=16−2−2=12。"],[]));

TID("c1-07","1.3","全等性质与线段、平行","证明三角形全等后，可用对应边相等得到线段关系，用对应角相等进一步证明平行；利用全等测距离的直接依据是对应边相等。","先证明全等，再明确指出目标量分别对应哪条边或哪个角；证明平行常把对应角转化为内错角或同位角。","全等只是中间工具，最终结论必须回到题目要求的线段或平行关系。",
 Q("证明题","D、E 分别是 △ABC 的边 AB、AC 的中点，F 在 DE 的延长线上，且 EF=DE。证明：（1）BD=FC；（2）AB∥CF。","BD=FC；AB∥CF",["D、E 为中点，所以 AD=BD、AE=CE。","在 △ADE 和 △CFE 中，AE=CE、∠AED=∠CEF、DE=FE，所以 △ADE≌△CFE（SAS）。","对应边 AD=CF，而 AD=BD，所以 BD=FC。","对应角 ∠A=∠ECF，所以 AB∥CF。"],[]),
 Q("选择题","利用全等三角形测量距离的依据是（　）。","B",["测量时把不可直接测量的线段转化为全等三角形的一条可测对应边。","依据是全等三角形对应边相等。"],["全等三角形的对应角相等","全等三角形的对应边相等","大小和形状相同的两个三角形全等","三边对应相等的两个三角形全等"]),
 Q("证明题","AB=DE，BF=EC，∠B=∠E，且 B、F、C、E 依次共线。证明 AC∥DF。","AC∥DF",["BF=EC，所以 BF+FC=EC+FC，即 BC=EF。","在 △ABC 和 △DEF 中，AB=DE、∠B=∠E、BC=EF，所以 △ABC≌△DEF（SAS）。","对应角 ∠ACB=∠DFE，因此 AC∥DF。"],[]),
 Q("证明题","A、F、C、D 在同一直线上，AB⊥BC，DE⊥EF，AB=DE，∠A=∠D。证明 AC=DF。","AC=DF",["AB⊥BC、DE⊥EF，所以 ∠B=∠E=90°。","结合 ∠A=∠D、AB=DE，得 △ABC≌△DEF（ASA）。","对应边 AC=DF。"],[]));

TID("c1-08","1.3","全等三角形综合应用","综合题常把角平分线、垂直、平行、中点、线段和差与全等判定组合使用，再由全等性质继续求角、求长或证明垂直。","先完成第一层全等，再把得到的边角关系作为第二层推理条件；多步题要分清每一步使用的三角形。","复杂图形中不要直接猜结论，必须逐层注明等角、等边来源和所用判定方法。",
 Q("解答题","在 △ABC 中，D 在 BC 上，AB=DB，BE 平分 ∠ABC，交 AC 于 E。（1）证明 △ABE≌△DBE；（2）若 ∠A=100°，∠C=50°，求 ∠DEB。","（1）△ABE≌△DBE（SAS）；（2）65°",["BE 平分 ∠ABC，所以 ∠ABE=∠DBE；AB=DB，BE 为公共边，因此 △ABE≌△DBE（SAS）。","∠ABC=180°−100°−50°=30°，所以 ∠ABE=15°。","在 △ABE 中，∠AEB=180°−100°−15°=65°。","由全等，∠DEB=∠AEB=65°。"],[]),
 Q("填空题","在 △ABC 中，∠ACB=90°，BC=6。过 B 作 BD⊥AB 且 BD=AB，延长 BC 到 E，使 CE=BC/2，连接 DE 并延长交 AC 于 F。若 DE=EF，则 AC=____。","12",["按材料作辅助线：过 D 作 DG⊥BE，利用 AAS 可证 △ABC≌△BDG，所以 AC=BG。","再由 DE=EF 及直角关系证明 △CFE≌△GDE（AAS），得到 CE=EG=3。","CG=CE+EG=6，因此 BG=BC+CG=12，故 AC=12。"],[]),
 Q("解答题","△ABC 中，D 在 BC 上，AB=AD；E 在 △ABC 外，AC=AE，且 ∠CAE=∠BAD，DE 与 AC 交于 O。（1）证明 △ABC≌△ADE；（2）若 ∠BAD=25°，求 ∠EDC。","（1）△ABC≌△ADE（SAS）；（2）25°",["由 ∠CAE=∠BAD，两边同加 ∠CAD，得 ∠DAE=∠BAC。","AB=AD、AC=AE，所以 △ABC≌△ADE（SAS）。","对应角 ∠C=∠E，结合对顶角 ∠AOE=∠DOC，可得 ∠EDC=∠CAE。","∠CAE=∠BAD=25°，所以 ∠EDC=25°。"],[]),
 Q("证明题","四边形 ABCD 中，AD∥BC，E 为 CD 中点。连接 AE、BE，延长 AE 交 BC 延长线于 F。若 AB=BC+AD，证明 BE⊥AF。","BE⊥AF",["由 AD∥BC 得 ∠ADE=∠FCE；E 为中点，DE=CE；对顶角 ∠AED=∠FEC。","所以 △ADE≌△FCE（ASA），得 AE=EF、AD=CF。","AB=BC+AD=BC+CF=BF。","在 △ABE 与 △FBE 中，AB=BF、AE=FE、BE 公共，所以两三角形 SSS 全等。","∠AEB=∠FEB 且二者互补，因此都为 90°，故 BE⊥AF。"],[]));
